enum {
    NEXTFIT, FIRSTFIT, BESTFIT, WORSTFIT, ALMOSTWORST,
    HARMONIC, KBOUNDED, FFD, BFD, WFD
};

const char *METHODS[] = {
    "NEXTFIT", "FIRSTFIT", "BESTFIT", "WORSTFIT", "ALMOSTWORST",
    "HARMONIC", "KBOUNDED", "FFD", "BFD", "WFD"
};
typedef struct { int number, size; } Item;

typedef struct {
    Item items[MAX_ITEMS];
    int count, load, category;
} Bin;
